def matmul(a: list[list[float]], b: list[list[float]]) -> list[list[float]]:
    if not a or not b or not a[0] or not b[0]:
        raise ValueError("Matrices cannot be empty")

    if len(set(len(row) for row in a)) != 1:
        raise ValueError("Matrix a must be rectangular")

    if len(set(len(row) for row in b)) != 1:
        raise ValueError("Matrix b must be rectangular")

    if len(a[0]) != len(b):
        raise ValueError("Inner dimensions of matrices must match")

    result = []
    for i in range(len(a)):
        row = []
        for j in range(len(b[0])):
            row.append(sum(a[i][k] * b[k][j] for k in range(len(b))))
        result.append(row)

    return result
