        threading.Thread(target=self.accept_connections, daemon=True).start()
        return self.port

    def stop(self):
        with self.lock:
            for client in self.clients.values():
                client['conn'].close()
            self.clients.clear()
        self.server_socket.close()

    def accept_connections(self):
        while True:
            conn, addr = self.server_socket.accept()
            threading.Thread(target=self.handle_client, args=(conn, addr), daemon=True).start()

    def handle_client(self, conn, addr):
        try:
            with self.lock:
                name = conn.recv(1024).decode('utf-8').strip()
                if name in self.clients:
                    conn.sendall(b'ERROR name taken\n')
                    conn.close()
                    return
                self.clients[name] = {'conn': conn, 'addr': addr}
                conn.sendall(b'OK\n')
                for other_name, other_client in self.clients.items():
                    if other_name != name:
                        other_client['conn'].sendall(f'* {name} joined\n'.encode('utf-8'))

            while True:
                message = conn.recv(1024).decode('utf-8').strip()
                if not message:
                    break
                with self.lock:
                    for other_name, other_client in self.clients.items():
                        if other_name != name:
                            other_client['conn'].sendall(f'{name}: {message}\n'.encode('utf-8'))

        except Exception as e:
            print(f"Error handling client {addr}: {e}")
        finally:
