import re
from typing import Callable, Dict, Tuple

class NotFound(Exception):
    pass

class MethodNotAllowed(Exception):
    pass

class Router:
    def __init__(self):
        self.routes: Dict[str, Dict[str, Tuple[Callable, Dict[str, str]]]] = {}

    def add(self, method: str, pattern: str, handler: Callable):
        if method not in self.routes:
            self.routes[method] = {}
        if pattern in self.routes[method]:
            raise ValueError(f"Route {method} {pattern} already exists")
        self.routes[method][pattern] = (handler, self._compile_pattern(pattern))

    def dispatch(self, method: str, path: str) -> Tuple[Callable, Dict[str, str]]:
        path = path.rstrip('/')
        for m, routes in self.routes.items():
            if m != method:
                continue
            for pattern, (handler, compiled_pattern) in routes.items():
                match = compiled_pattern.match(path)
                if match:
                    return handler, match.groupdict()
        raise NotFound(f"No route found for {method} {path}")

    def _compile_pattern(self, pattern: str) -> re.Pattern:
        pattern = pattern.replace('{', '(?P<').replace('}', '>.+?)')
        return re.compile(f'^{pattern}$')
