def to_roman(n: int) -> str:
    if not (1 <= n <= 3999):
        raise ValueError("Input must be in the range 1..3999")

    val = [
        1000, 900, 500, 400,
        100, 90, 50, 40,
        10, 9, 5, 4,
        1
    ]
    syms = [
        "M", "CM", "D", "CD",
        "C", "XC", "L", "XL",
        "X", "IX", "V", "IV",
        "I"
    ]

    roman_num = ''
    i = 0
    while n > 0:
        for _ in range(n // val[i]):
            roman_num += syms[i]
            n -= val[i]
        i += 1
    return roman_num

def from_roman(s: str) -> int:
    if not s.isupper() or not all(c in "IVXLCDM" for c in s):
        raise ValueError("Input must be in upper-case canonical Roman numeral form")

    val = {
        "I": 1, "V": 5, "X": 10, "L": 50,
        "C": 100, "D": 500, "M": 1000
    }
    total = 0
    prev_value = 0

    for char in reversed(s):
        value = val[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value

    return total
